// EXPORTS: IKpiDailyRecord, calculateKpiMetrics, getKpiStatus, STORAGE_KEY_KPI, SITE_OPTIONS, DEFAULT_SITE

import { scopedStorage } from '@lark-apaas/client-toolkit-lite';

export interface IKpiDailyRecord {
  id: string;
  date: string; // YYYY-MM-DD
  username: string; // 归属账号
  nickname: string; // 昵称（展示用）
  orderCount: number; // 出单数
  listingCount: number; // 上架数
  adSpend: number; // 广告花费 USD
  adSales: number; // 广告带来的销售额 USD
  totalVisits: number; // 总访问量
  refundCount: number; // 退款数
  costPerUnit: number; // ⚠️ 历史兼容字段（旧数据用，新表单不再手动录入）
  totalSales: number; // 当天总出单销售额
  naturalOrders: number; // 自然单数 = 总单 - 广告单
  totalCost: number; // 总成本费（总货成本，人民币 CNY）
  site: string; // 主要站点，如 'us' / 'jp' / 'ca' 等
  currency: string; // 币种，如 'USD' / 'JPY' / 'CAD' 等
  note: string; // 今日特殊备忘/调整
  createdAt: number;
}

export interface KpiMetrics {
  acos: number; // ACOS = 广告花费 / 广告销售额
  conversionRate: number; // 转化率 = 出单数 / 总访问量
  roi: number; // ROI = (广告销售额 - 广告花费 - 货成本) / 广告花费
  refundRate: number; // 退款率 = 退款数 / 出单数
  totalSales: number; // 总销售额（优先用录入的总销售额，无则用广告销售额近似）
  totalCost: number; // 总成本 = 广告花费 + 货成本
  tacos: number; // TACOS = 广告花费 / 总销售额
  naturalOrderRate: number; // 自然单占比
}

export interface SiteOption {
  value: string;
  label: string;
  currency: string;
}

