export type KpiStatusLevel = 'green' | 'orange' | 'red';

export interface KpiStatus {
  level: KpiStatusLevel;
  label: string;
  color: string;
  bg: string;
}

const STORAGE_KEY_KPI = 'kpi_records';
export { STORAGE_KEY_KPI };

/**
 * 根据多条记录汇总计算指标（支持单日/月度/任意区间汇总）
 * 汇总逻辑：分子分母分别相加后再相除，不是各天指标取平均
 */
export function calculateKpiMetrics(records: IKpiDailyRecord[]): KpiMetrics {
  const totalOrders = records.reduce((sum, r) => sum + r.orderCount, 0);
  const totalAdSpend = records.reduce((sum, r) => sum + r.adSpend, 0);
  const totalAdSales = records.reduce((sum, r) => sum + r.adSales, 0);
  const totalVisits = records.reduce((sum, r) => sum + r.totalVisits, 0);
  const totalRefunds = records.reduce((sum, r) => sum + r.refundCount, 0);
  const totalGoodsCost = records.reduce((sum, r) => sum + r.orderCount * r.costPerUnit, 0);
  const totalNaturalOrders = records.reduce((sum, r) => sum + (r.naturalOrders || 0), 0);
  // 总销售额：优先用显式录入的 totalSales，没有则回退到广告销售额（旧数据兼容）
  const totalSales = records.reduce(
    (sum, r) => sum + (r.totalSales && r.totalSales > 0 ? r.totalSales : r.adSales),
    0,
  );

  const acos = totalAdSales > 0 ? totalAdSpend / totalAdSales : 0;
  const conversionRate = totalVisits > 0 ? totalOrders / totalVisits : 0;
  const totalCost = totalAdSpend + totalGoodsCost;
  const roi = totalAdSpend > 0 ? (totalAdSales - totalCost) / totalAdSpend : 0;
  const refundRate = totalOrders > 0 ? totalRefunds / totalOrders : 0;
  const tacos = totalSales > 0 ? totalAdSpend / totalSales : 0;
  const naturalOrderRate = totalOrders > 0 ? totalNaturalOrders / totalOrders : 0;

  return {
    acos,
    conversionRate,
    roi,
    refundRate,
    totalSales,
    totalCost,
    tacos,
    naturalOrderRate,
  };
}

/**
 * 获取各项指标的红黄绿状态
 */
export function getKpiStatus(metrics: KpiMetrics, orderCount: number): {
  overall: KpiStatus;
  acos: KpiStatus;
  conversion: KpiStatus;
  refund: KpiStatus;
  zeroOrder: boolean;
} {
  const zeroOrder = orderCount === 0;

  // ACOS: >40% 红、25%~40% 橙、≤25% 绿
  let acos: KpiStatus;
  if (metrics.acos > 0.4) {
    acos = { level: 'red', label: '过高', color: '#dc2626', bg: 'rgba(220,38,38,0.1)' };
  } else if (metrics.acos > 0.25) {
    acos = { level: 'orange', label: '偏高', color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' };
  } else {
    acos = { level: 'green', label: '健康', color: '#16a34a', bg: 'rgba(22,163,74,0.1)' };
  }

  // 转化率: <5% 红、5%~8% 橙、≥8% 绿
  let conversion: KpiStatus;
  if (metrics.conversionRate < 0.05) {
    conversion = { level: 'red', label: '偏低', color: '#dc2626', bg: 'rgba(220,38,38,0.1)' };
  } else if (metrics.conversionRate < 0.08) {
    conversion = { level: 'orange', label: '一般', color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' };
  } else {
    conversion = { level: 'green', label: '良好', color: '#16a34a', bg: 'rgba(22,163,74,0.1)' };
  }

  // 退款率: >10% 红、5%~10% 橙、≤5% 绿
  let refund: KpiStatus;
  if (metrics.refundRate > 0.1) {
    refund = { level: 'red', label: '过高', color: '#dc2626', bg: 'rgba(220,38,38,0.1)' };
  } else if (metrics.refundRate > 0.05) {
    refund = { level: 'orange', label: '偏高', color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' };
  } else {
    refund = { level: 'green', label: '健康', color: '#16a34a', bg: 'rgba(22,163,74,0.1)' };
  }

  // 综合状态：任一红色则红，否则任一橙色则橙，全绿才绿
  let overall: KpiStatus;
  if (zeroOrder || acos.level === 'red' || conversion.level === 'red' || refund.level === 'red') {
    overall = { level: 'red', label: '需关注', color: '#dc2626', bg: 'rgba(220,38,38,0.1)' };
  } else if (acos.level === 'orange' || conversion.level === 'orange' || refund.level === 'orange') {
    overall = { level: 'orange', label: '待优化', color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' };
  } else {
    overall = { level: 'green', label: '健康', color: '#16a34a', bg: 'rgba(22,163,74,0.1)' };
  }

  return { overall, acos, conversion, refund, zeroOrder };
}

// ========== 存储读取工具 ==========

export function loadAllRecords(): IKpiDailyRecord[] {
  try {
    const raw = scopedStorage.getItem(STORAGE_KEY_KPI);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    // 历史兼容：老数据 dayCost 字段迁移到 totalCost；无 totalCost 时置 0
    return parsed.map(r => ({
      ...r,
      totalCost: r.totalCost ?? r.dayCost ?? 0,
      currency: r.currency || 'USD',
      site: r.site || 'us',
      naturalOrders: r.naturalOrders ?? 0,
      totalSales: r.totalSales ?? 0,
    }));
  } catch {
    return [];
  }
}

export function saveAllRecords(records: IKpiDailyRecord[]) {
  try {
    scopedStorage.setItem(STORAGE_KEY_KPI, JSON.stringify(records));
  } catch {
    // 存储失败静默
  }
}

export function loadUserRecords(username: string): IKpiDailyRecord[] {
  const all = loadAllRecords();
  return all.filter(r => r.username === username).sort((a, b) => b.date.localeCompare(a.date));
}

export function addRecord(record: IKpiDailyRecord) {
  const all = loadAllRecords();
  // 同一天同账号覆盖
  const existingIdx = all.findIndex(r => r.username === record.username && r.date === record.date);
  if (existingIdx >= 0) {
    // 合并：保留历史字段（如 costPerUnit 旧值），新字段覆盖
    all[existingIdx] = {
      ...all[existingIdx],
      ...record,
      id: all[existingIdx].id,
      createdAt: all[existingIdx].createdAt,
    };
  } else {
    all.push(record);
  }
  saveAllRecords(all);
}

export function deleteRecord(id: string) {
  const all = loadAllRecords().filter(r => r.id !== id);
  saveAllRecords(all);
}

// ========== 日期工具 ==========

export function formatDate(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

export function getTodayDate(): string {
  return formatDate(new Date());
}

export function getDaysAgo(n: number): string {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return formatDate(d);
}

export function getMonthRange(): { start: string; end: string } {
  const now = new Date();
  const start = formatDate(new Date(now.getFullYear(), now.getMonth(), 1));
  const end = formatDate(now);
  return { start, end };
}

/**
 * 获取近 N 天的日期数组（含今天），倒序 [今天, 昨天, ...]
 */
export function getRecentDays(n: number): string[] {
  const days: string[] = [];
  for (let i = 0; i < n; i++) {
    days.push(getDaysAgo(i));
  }
  return days;
}
